Given a sorted array of distinct positive integers arr[] and an integer k, find the kth positive integer that is missing from the array.Examples : Input: arr[] = [2, 3, 4, 7, 11], k = 5Output: 9Explanation: Missing are 1, 5, 6, 8, 9, 10, ... and 5th missing number is 9.Input: arr[] = [1, 2, 3], k = 2Output: 5Explanation: Missing are 4, 5, 6.... and 2nd missing number is 5.Input: arr[] = [3, 5, 9, 10, 11, 12], k = 2Output: 2Explanation: Missing are 1, 2, 4, 6, 7, 8, 13,...  and 2nd missing number is 2.Try It YourselfTable of Content[Naive Approach] Using Hash Set - O(n + k) Time and O(n) Space[Better Approach] Using Index Comparison - O(n) Time and O(1) Space[Expected Approach] Using Binary Search - O(log n) Time and O(1) Space[Naive Approach] Using Hash Set - O(n + k) Time and O(n) SpaceThe idea is to insert all elements of the array into a set for constant-time lookups. Then, we iterate starting from 1, checking whether each number is missing from the set. For every number not found, we increment a counter. Once we reach the k-th missing number, we return it as the result.
            C++

    #include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int kthMissing(vector<int>& arr, int k) {

    // insert all array elements into a set
    unordered_set<int> s(arr.begin(), arr.end());

    // loop until we find the k-th missing number
    int count = 0, curr = 0;
    while (count < k) {
        curr++;

        // increment missing count if current
        // element is missing
        if (s.find(curr) == s.end()) {
            count++;
        }      
    }
    return curr;
}

int main() {
    vector<int> arr = {2, 3, 4, 7, 11};
    int k = 5;
    cout << kthMissing(arr, k);
    return 0;
}


